// PruneEmpty removes all products with zero stock and returns the count of removed products.
func (st *ProductStore) PruneEmpty() (int, bool) {
	st.mu.Lock()
	defer st.mu.Unlock()
	removedCount := 0
	for id, p := range st.items {
