	if req.Stock < 0 {
		return validationError{"stock", "must not be negative"}
	}
	return nil
}

func (s *Server) handleListProducts(w http.ResponseWriter, r *http.Request) {
	var lowStock bool
	if r.URL.Query().Get("low_stock") == "true" {
		lowStock = true
	} else if r.URL.Query().Get("low_stock") == "false" {
		lowStock = false
	} else {
