	var filtered []Product
	if lowStock {
		for _, p := range s.products.List() {
			if p.Stock < 5 {
				filtered = append(filtered, p)
			}
		}
	} else {
		for _, p := range s.products.List() {
			if p.Stock >= 5 {
				filtered = append(filtered, p)
			}
		}
	}

