	ID    string `json:"id"`
	Email string `json:"email"`
	Name  string `json:"name"`
}

// UserStore is an in-memory, concurrency-safe store of users.
type UserStore struct {
	mu    sync.RWMutex
	items map[string]User
	seq   int
}

func NewUserStore() *UserStore {
	return &UserStore{items: make(map[string]User)}
}

// Create assigns the next ID, stores the user, and returns the stored copy.
func (st *UserStore) Create(u User) User {
	st.mu.Lock()
	defer st.mu.Unlock()
	st.seq++
	u.ID = formatID("usr", st.seq)
	st.items[u.ID] = u
	return u
}

func (st *UserStore) Get(id string) (User, bool) {
	st.mu.RLock()
	defer st.mu.RUnlock()
	u, ok := st.items[id]
	return u, ok
}

// FindByEmail matches case-insensitively.
func (st *UserStore) FindByEmail(email string) (User, bool) {
	st.mu.RLock()
	defer st.mu.RUnlock()
	for _, u := range st.items {
		if strings.EqualFold(u.Email, email) {
			return u, true
		}
	}
	return User{}, false
}

// List returns all users sorted by ID.
func (st *UserStore) List() []User {
	st.mu.RLock()
	defer st.mu.RUnlock()
	out := make([]User, 0, len(st.items))
	for _, u := range st.items {
		out = append(out, u)
	}
	slices.SortFunc(out, func(a, b User) int { return strings.Compare(a.ID, b.ID) })
	return out
}

// Delete reports whether the user existed.
func (st *UserStore) Delete(id string) bool {
	st.mu.Lock()
	defer st.mu.Unlock()
	if _, ok := st.items[id]; !ok {
		return false
	}
	delete(st.items, id)
	return true

// ListByName returns users whose name exactly matches the given name, ordered by ID.
func (st *UserStore) ListByName(name string) []User {
	st.mu.RLock()
	defer st.mu.RUnlock()
	var results []User
	found := false
	for _, u := range st.items {
		if u.Name == name {
			results = append(results, u)
			found = true
		}
	}
	if !found {
		results = results // empty slice, non-nil
	}
	slices.SortFunc(results, func(a, b User) int { return strings.Compare(a.ID, b.ID) })
	return results
}

