	}
	slices.SortFunc(out, func(a, b Product) int { return strings.Compare(a.ID, b.ID) })
	return out
}

// PruneEmpty removes all products with stock zero and returns the count of removed products.
func (st *ProductStore) PruneEmpty() (int, bool) {
	st.mu.Lock()
	defer st.mu.Unlock()
	removedCount := 0
	for id, p := range st.items {
		if p.Stock == 0 {
			delete(st.items, id)
			removedCount++
		}
	}
	return removedCount, true
}

